    v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat(v1_rt::concat("// -- Rc-wrapped container operations (FF-8) ---------------------------------\n".to_string(), "// These mirror the bare Vec/HashMap functions above but operate on Rc-wrapped\n".to_string()), "// containers for O(1) clone cost. Generated code using Rc container templates\n".to_string()), "// will call these. Read-only functions (map_get, map_keys, map_values, lookup,\n".to_string()), "// map_contains_key, map_has) work with Rc<HashMap> via auto-deref.\n\n".to_string()), "pub fn rc_list_push<T: Clone>(list: Rc<Vec<T>>, item: T) -> Rc<Vec<T>> {\n".to_string()), "    let mut v = list;\n".to_string()), "    Rc::make_mut(&mut v).push(item);\n".to_string()), "    v\n".to_string()), "}\n\n".to_string()), "pub fn rc_list_concat<T: Clone>(a: Rc<Vec<T>>, b: Rc<Vec<T>>) -> Rc<Vec<T>> {\n".to_string()), "    let mut result = a;\n".to_string()), "    Rc::make_mut(&mut result).extend(b.iter().cloned());\n".to_string()), "    result\n".to_string()), "}\n\n".to_string()), "pub fn rc_map_insert<K: std::cmp::Eq + std::hash::Hash + Clone, V: Clone>(map: Rc<HashMap<K, V>>, key: K, value: V) -> Rc<HashMap<K, V>> {\n".to_string()), "    let mut m = map;\n".to_string()), "    Rc::make_mut(&mut m).insert(key, value);\n".to_string()), "    m\n".to_string()), "}\n\n".to_string()), "pub fn rc_map_merge<K: std::cmp::Eq + std::hash::Hash + Clone, V: Clone>(base: Rc<HashMap<K, V>>, overlay: Rc<HashMap<K, V>>) -> Rc<HashMap<K, V>> {\n".to_string()), "    let mut result = base;\n".to_string()), "    let inner = Rc::make_mut(&mut result);\n".to_string()), "    for (k, v) in overlay.iter() {\n".to_string()), "        inner.insert(k.clone(), v.clone());\n".to_string()), "    }\n".to_string()), "    result\n".to_string()), "}\n\n".to_string()), "pub fn rc_index_by<V: Clone, F: Fn(&V) -> String>(list: Rc<Vec<V>>, key_fn: F) -> Rc<HashMap<String, V>> {\n".to_string()), "    Rc::new(list.iter().map(|v| (key_fn(v), v.clone())).collect())\n".to_string()), "}\n\n".to_string()), "pub fn rc_empty_map<K: std::cmp::Eq + std::hash::Hash, V>() -> Rc<HashMap<K, V>> { Rc::new(HashMap::new()) }\n\n".to_string()), "impl<T: Clone> V2Concat for Rc<Vec<T>> {\n".to_string()), "    fn v1_concat(self, other: Rc<Vec<T>>) -> Rc<Vec<T>> { rc_list_concat(self, other) }\n".to_string()), "}\n\n".to_string())
